let sensors = msg.payload;

// نجيب Sensor 1 فقط
let sensor = sensors.find(s => s.device_id === "sensor 1");

if (!sensor) {
    node.warn("Sensor 1 not found");
    return null;
}

let values = {
    "Temperature": sensor.avg_temp,
    "Humidity": sensor.avg_humidity,
    "Pressure": sensor.avg_pressure,
    "AirQuality": sensor.avg_air_quality,
    "Noise": sensor.avg_noise_level,
    "Battery": sensor.avg_battery_level
};

// إرسال 6 رسائل (لكل Gauge)
for (let key in values) {
    node.send({
        topic: key,        // يظهر على كل Gauge
        payload: values[key]  // القيمة المعروضة
    });
}

return null;

